switchBoxModelID = 364function replaceSwitchBoxModel()	boxTXD = engineLoadTXD("files/switchbox.txd")	engineImportTXD(boxTXD, switchBoxModelID)		boxCol = engineLoadCOL("files/switchbox.col")	engineReplaceCOL(boxCol, switchBoxModelID)		boxDff = engineLoadDFF("files/switchbox.dff", switchBoxModelID)	engineReplaceModel(boxDff, switchBoxModelID)endaddEventHandler("onClientResourceStart", resourceRoot, replaceSwitchBoxModel)